// Decides whether one SMS may go out now, under US rules.
// Pure function: sends nothing and keeps no state. The caller sends only when allowed is true.
//
// Marketing texts (47 CFR 64.1200):
//   - the customer must have opted in to marketing (marketingConsent === true)
//   - a STOP reply (optedOutAt set) blocks them
//   - they may go only 08:00 to 21:00 in the customer's own time zone (64.1200(c)(1))
// Transactional texts (customer-triggered: login codes, delivery updates) are not
// blocked by consent, STOP or hours. Only the phone format and the kind are checked.

const MARKETING_START_MINUTE = 8 * 60; // 08:00 local, included
const MARKETING_END_MINUTE = 21 * 60; // 21:00 local, excluded

// North American Numbering Plan: +1, area code and exchange start with 2-9.
const NANP_E164 = /^\+1[2-9]\d{2}[2-9]\d{6}$/;

function block(reason) {
  return { allowed: false, reason };
}

// Minute of the day (0-1439) at `now` in `timeZone`, or null when the zone is unknown.
// Passing an explicit zone keeps the server's own zone out of the result.
function localMinuteOfDay(now, timeZone) {
  if (typeof timeZone !== 'string' || timeZone === '') return null;
  let parts;
  try {
    parts = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      hour: '2-digit',
      minute: '2-digit',
    }).formatToParts(now);
  } catch {
    return null;
  }
  const hour = Number(parts.find((p) => p.type === 'hour').value);
  const minute = Number(parts.find((p) => p.type === 'minute').value);
  return hour * 60 + minute;
}

export function checkSms(message, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return block('invalid_now');

  const kind = message?.kind;
  if (kind !== 'marketing' && kind !== 'transactional') return block('invalid_kind');

  const to = message.to;
  if (typeof to?.phone !== 'string' || !NANP_E164.test(to.phone)) return block('invalid_phone');

  if (kind === 'transactional') {
    return { allowed: true, reason: null };
  }

  // Marketing from here on.
  if (to.optedOutAt !== null && to.optedOutAt !== undefined) return block('opted_out');
  if (to.marketingConsent !== true) return block('no_marketing_consent');

  const minute = localMinuteOfDay(now, to.timeZone);
  if (minute === null) return block('invalid_time_zone');
  if (minute < MARKETING_START_MINUTE || minute >= MARKETING_END_MINUTE) {
    return block('outside_marketing_hours');
  }

  return { allowed: true, reason: null };
}

input.command:
for TZV in UTC Asia/Tokyo America/Los_Angeles; do echo "== server TZ=$TZV"; TZ=$TZV node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from './bot.mjs';
const to = (o = {}) => ({ phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null, ...o });
const mk = (o = {}) => ({ kind: 'marketing', body: 'Sale', to: to(o) });
const tx = (o = {}) => ({ kind: 'transactional', body: 'Code 123', to: to(o) });
const at = (iso) => new Date(iso);
const ok = { allowed: true, reason: null };
const no = (r) => ({ allowed: false, reason: r });
// Oct 23 2026 is CDT (UTC-5); Nov 2 2026 is CST (UTC-6, after DST ends Nov 1)
assert.deepEqual(checkSms(mk(), at('2026-10-23T15:00:00Z')), ok);          // 10:00 CDT
assert.deepEqual(checkSms(mk(), at('2026-10-23T13:00:00Z')), ok);          // 08:00 CDT, start included
assert.deepEqual(checkSms(mk(), at('2026-10-23T12:59:00Z')), no('outside_marketing_hours')); // 07:59
assert.deepEqual(checkSms(mk(), at('2026-10-23T01:59:00Z')), ok);          // 20:59 CDT
assert.deepEqual(checkSms(mk(), at('2026-10-23T02:00:00Z')), no('outside_marketing_hours')); // 21:00 end excluded
assert.deepEqual(checkSms(mk(), at('2026-11-02T14:00:00Z')), ok);          // 08:00 CST
assert.deepEqual(checkSms(mk(), at('2026-11-02T13:59:00Z')), no('outside_marketing_hours')); // 07:59 CST
assert.deepEqual(checkSms(mk({ optedOutAt: '2026-10-01T12:00:00Z' }), at('2026-10-23T15:00:00Z')), no('opted_out'));
assert.deepEqual(checkSms(mk({ marketingConsent: false }), at('2026-10-23T15:00:00Z')), no('no_marketing_consent'));
assert.deepEqual(checkSms(mk({ timeZone: 'Mars/Olympus' }), at('2026-10-23T15:00:00Z')), no('invalid_time_zone'));
assert.deepEqual(checkSms(mk({ timeZone: undefined }), at('2026-10-23T15:00:00Z')), no('invalid_time_zone'));
assert.deepEqual(checkSms(tx({ marketingConsent: false, optedOutAt: '2026-10-01T12:00:00Z' }), at('2026-10-23T08:00:00Z')), ok); // 03:00 local, transactional
assert.deepEqual(checkSms(mk({ phone: '3125550142' }), at('2026-10-23T15:00:00Z')), no('invalid_phone'));
assert.deepEqual(checkSms({ kind: 'promo', body: 'x', to: to() }, at('2026-10-23T15:00:00Z')), no('invalid_kind'));
assert.deepEqual(checkSms(mk(), new Date('nope')), no('invalid_now'));
const codes = ['invalid_now','invalid_kind','invalid_phone','opted_out','no_marketing_consent','invalid_time_zone','outside_marketing_hours'];
assert.equal(new Set(codes).size, codes.length);
console.log('all assertions passed');
EOF
done
